@Controller
@RequestMapping("/clientes")
public class ClienteController {

    @Autowired
    private ClienteService clienteService; // Nuestro Modelo

    @GetMapping("/listar")
    public String listarClientes(Model model) {
        // 1. Hablamos con el Modelo
        List<Cliente> lista = clienteService.buscarTodos();

        // 2. Preparamos el paquete para la Vista
        model.addAttribute("titulo", "Listado de Clientes");
        model.addAttribute("clientes", lista);

        // 3. Decidimos qué Vista mostrar
        return "vista_lista_clientes"; 
    }
}

